/* eslint-disable max-len */

'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var dlartg = require( './../lib/ndarray.js' );


// FIXTURES //

var G_EQ_ZERO = require( './fixtures/g_eq_zero.json' );
var F_EQ_ZERO = require( './fixtures/f_eq_zero.json' );
var NONZERO_VALUES = require( './fixtures/nonzero.json' );
var LARGE_VALUES = require( './fixtures/large_values.json' );

var OFFSET_G_EQ_ZERO = require( './fixtures/offsets/g_eq_zero.json' );
var OFFSET_F_EQ_ZERO = require( './fixtures/offsets/f_eq_zero.json' );
var OFFSET_NONZERO_VALUES = require( './fixtures/offsets/nonzero.json' );
var OFFSET_LARGE_VALUES = require( './fixtures/offsets/large_values.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlartg, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 10', function test( t ) {
	t.strictEqual( dlartg.length, 10, 'returns expected value' );
	t.end();
});

tape( 'the function returns expected values for G = 0', function test( t ) {
	var expectedS;
	var expectedC;
	var expectedR;
	var data;
	var F;
	var G;
	var S;
	var C;
	var R;

	data = G_EQ_ZERO;

	F = new Float64Array( data.F );
	G = new Float64Array( data.G );
	S = new Float64Array( data.S );
	C = new Float64Array( data.C );
	R = new Float64Array( data.R );

	expectedC = new Float64Array( data.C_out );
	expectedS = new Float64Array( data.S_out );
	expectedR = new Float64Array( data.R_out );

	dlartg( F, data.offsetF, G, data.offsetG, C, data.offsetC, S, data.offsetS, R, data.offsetR );

	t.deepEqual( S, expectedS, 'returns expected value' );
	t.deepEqual( C, expectedC, 'returns expected value' );
	t.deepEqual( R, expectedR, 'returns expected value' );
	t.end();
});

